# AFTER (regressed): autotune num_stages + direct B load
@triton.autotune(configs=[Config({}, num_stages=1, num_warps=4), Config({}, num_stages=2, num_warps=4), ...], key=[])
@triton.jit
def kernel(...):
    for k_idx in range(cdiv(K, BLOCK_K)):
        a = tl.load(A + k_offs + K*m_offs)  # [BLOCK_M, BLOCK_K]
        k_offs2 = offs_k[:,None] + k_idx*BLOCK_K  # [BLOCK_K, 1]
        n_offs = offs_b_n[None,:]               # [1, BLOCK_N]
        b = tl.load(B + k_offs2 + n_offs*512)   # [BLOCK_K, BLOCK_N] direct
        acc += tl.dot(a, b)
# Result: 53 regs/thread, 8KB smem, 39.81us, warp_cycles=10.44

fast_pseudocode:
# BEFORE (faster): no autotune num_stages sweep + tl.trans B load
@triton.autotune(configs=[Config({}, num_warps=4, num_stages=3), Config({}, num_warps=4, num_stages=4), ...], key=[])
@triton.jit
def kernel(...):
    for k_idx in range(cdiv(K, BLOCK_K)):
        a = tl.load(A + xindex)  # [BLOCK_M, BLOCK_K]
        b_ptrs = B + (offs_b_n[:,None]*512 + b_k_vals)  # [BLOCK_N, BLOCK_K]
        b = tl.trans(tl.load(b_ptrs))  # transpose to [BLOCK_K, BLOCK_N]
        acc += tl.dot(a, b)
# Result: 64 regs/thread, 16KB smem, 31.04us, warp_cycles=7.62
